# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, P, J, PA, A, V, E, K, AD = "Lucas", "Pepe", "Juanjo", "Paco", "Amparo", "Vicente", "Encarna", "Min-seo", "Adrián"
D = [
("#", "Escena 1 · 6:40 · Nave del horno uno", "장면 1 · 오전 6시 40분 · 1호기 작업동"),
(None, "Lunes 4 de mayo. Todavía no ha salido el sol. La nave del horno uno huele a pintura nueva y a aceite de rodillos. Ciento veinte metros de horno, de punta a punta, con el número «1» recién pintado de verde junto al quemador principal. Pepe camina despacio a lo largo de la línea, con una linterna y una libreta. Paco lo sigue dos pasos por detrás.", "5월 4일 월요일. 아직 해가 뜨지 않았다. 1호기 작업동에서 새 페인트와 롤러 기름 냄새가 난다. 끝에서 끝까지 120미터인 가마. 주 버너 옆에는 초록색으로 새로 칠한 '1' 자. 페페가 손전등과 수첩을 들고 라인을 따라 천천히 걷는다. 파코가 두 걸음 뒤에서 따라간다."),
(PA, "Pepe, ya lo has revisado tres veces. Desde las cinco.", "페페, 벌써 세 번 확인했어요. 5시부터."),
(P, "Cuatro. La primera fue en casa, en sueños.", "네 번이야. 첫 번째는 집에서, 꿈속에서 했어."),
(PA, "¿Y qué tal en sueños?", "꿈속에선 어땠는데요?"),
(P, "En sueños, el rodillo cuarenta y dos hacía un ruido raro. Así que he venido a escucharlo despierto.", "꿈에선 42번 롤러가 이상한 소리를 냈어. 그래서 깨어 있을 때 들어 보러 온 거야."),
(PA, "¿Y?", "그래서요?"),
(P, "Nada. Calla como un muerto. Como debe ser.", "아무 소리도 없어. 죽은 듯 조용해. 그래야지."),
(None, "Se abre la puerta lateral. Entra Lucas, con dos cafés de máquina. Detrás, Juanjo, con el mono del turno y las manos en los bolsillos.", "옆문이 열린다. 루카스가 자판기 커피 두 잔을 들고 들어온다. 뒤로 작업복을 입은 후안호가 두 손을 주머니에 넣은 채 따라 들어온다."),
(L, "Buenos días. Toni me ha dicho que estabais aquí desde las cinco.", "좋은 아침이에요. 토니가 다들 5시부터 여기 있었다던데요."),
(P, "Toni dice muchas cosas. Pero esa es verdad.", "토니는 말이 많지. 근데 그건 맞아."),
(L, "Te he traído un café. Uno solo. Paco, el tuyo me lo he bebido por el camino, lo siento.", "커피 가져왔어요. 한 잔만요. 파코, 당신 건 오는 길에 내가 마셔 버렸어요, 미안해요."),
(PA, "(ríe) Ya lo sabía. Desde Seúl vienes bebiendo café como un coreano.", "(웃으며) 그럴 줄 알았어요. 서울 다녀오더니 한국 사람처럼 커피를 마시네."),
(J, "Buenos días a todos. (se aclara la garganta) Pepe, ¿de verdad tengo que hacerlo yo?", "다들 좋은 아침이에요. (헛기침하며) 페페, 정말 제가 해야 해요?"),
(P, "Tú. Lo dije en enero y lo dije en marzo. Lo que digo dos veces ya no se cambia.", "너. 1월에도 말했고 3월에도 말했어. 두 번 말한 건 안 바뀌어."),
(J, "Es que yo no he encendido un horno en mi vida. Yo cierro cajas.", "근데 저는 평생 가마에 불을 붙여 본 적이 없어요. 전 상자를 닫는 사람이에요."),
(P, "Por eso. Encender es lo fácil: un botón y una llave. Lo difícil es lo de antes y lo de después. Y eso lo hacemos nosotros.", "그러니까. 불 붙이는 건 쉬운 거야. 버튼 하나랑 열쇠 하나. 어려운 건 그 전이랑 그 후고. 그건 우리가 해."),
(J, "¿Y si no arranca?", "안 켜지면요?"),
(P, "Arranca. El veintiocho lo probamos en caliente y arrancó a la primera. Se nota que tiene ganas.", "켜져. 28일에 열간 시험했는데 한 번에 켜졌어. 이 녀석도 하고 싶어 하는 게 느껴져."),
(L, "Juanjo, si te sirve de algo: yo tampoco sabía lo que era un atomizador hace quince meses. Y aquí sigo.", "후안호, 도움이 될지 모르겠지만, 나도 15개월 전엔 분무건조기가 뭔지 몰랐어요. 그런데 아직 여기 있잖아요."),
(J, "Ya. Pero a ti no te mira toda la fábrica mientras aprietas un botón.", "그렇죠. 근데 당신은 버튼 누를 때 공장 전체가 쳐다보진 않잖아요."),
(PA, "Toda no. Solo la mitad. La otra mitad estará mirando el móvil.", "전체는 아니고 절반만. 나머지 절반은 휴대폰 보고 있을 거예요."),
(J, "(sonríe por primera vez) Eso me tranquiliza mucho, Paco. Gracias.", "(처음으로 웃으며) 그거 참 위로가 되네요, 파코. 고마워요."),
(L, "Pepe, una cosa antes de que llegue la gente. Faisal me preguntó en Riad si sigues yendo en junio.", "페페, 사람들 오기 전에 하나만요. 리야드에서 파이살이 6월에 아직 오시는 거냐고 물었어요."),
(P, "Voy. Cuatro vestíbulos, está en el anexo. Lo firmaste tú.", "가. 로비 네 곳, 부속서에 있잖아. 네가 서명했고."),
(L, "Lo firmé yo, pero el que va eres tú. ¿Y quién se queda aquí con el uno recién encendido?", "서명은 내가 했지만 가는 건 당신이죠. 그럼 막 불 붙인 1호기는 누가 지켜요?"),
(P, "Paco. (sin mirarlo) Paco ya sabe más de lo que se cree.", "파코. (그를 보지도 않고) 파코는 자기가 생각하는 것보다 이미 더 많이 알아."),
(PA, "¿Yo? Pepe, con el tres me apaño, pero el uno…", "저요? 페페, 3호기는 어떻게든 하겠는데, 1호기는…"),
(P, "Con el uno, igual. Los hornos son como las personas: cada uno tiene su genio, pero todos quieren lo mismo. Que no los fuerces.", "1호기도 똑같아. 가마는 사람 같아서 저마다 성질이 있지만 원하는 건 다 같아. 억지로 몰아붙이지 않는 거."),
(None, "Pepe se acerca a Juanjo y, sin decir nada, le coloca bien el cuello del mono. Luego le da una palmada en el hombro con la mano derecha. Juanjo mira la mano izquierda, la suya, la de los tres dedos, y asiente.", "페페가 후안호에게 다가가 아무 말 없이 작업복 깃을 바로잡아 준다. 그리고 오른손으로 어깨를 툭 친다. 후안호는 손가락이 세 개뿐인 자기 왼손을 내려다보고는 고개를 끄덕인다."),
(P, "A las ocho. Ni un minuto antes.", "8시. 1분도 먼저는 안 돼."),
(J, "Ni un minuto antes.", "1분도 먼저는 안 돼요."),

("#", "Escena 2 · 8:00 · Encendido del horno uno", "장면 2 · 오전 8시 · 1호기 점화"),
(None, "La nave se ha llenado. Están los veintiún nuevos, con los chalecos todavía sin manchas; los del turno de noche, que no se han ido a casa; Maribel, con su tablet; Toni, que ha dejado la garita a un compañero. Vicente, Amparo y Encarna, la presidenta del comité, esperan junto al panel de control. Nadie ha preparado un discurso. O eso dicen.", "작업동이 사람들로 가득 찼다. 조끼에 아직 얼룩 하나 없는 신입 21명, 집에 가지 않은 야간조, 태블릿을 든 마리벨, 경비실을 동료에게 맡기고 온 토니. 비센테와 암파로, 그리고 노조 대표 엔카르나가 제어판 옆에서 기다린다. 아무도 연설을 준비하지 않았다. 다들 그렇게 말한다."),
(V, "Bueno. No he preparado nada, así que voy a ser breve. Escuchad un momento, por favor.", "자. 아무것도 준비 안 했으니 짧게 할게. 잠깐만 들어 줘."),
(PA, "(en voz baja, a Lucas) Lleva desde el viernes ensayando en el despacho. Lo he oído yo.", "(작은 소리로 루카스에게) 금요일부터 사무실에서 연습하셨어요. 내가 들었어요."),
(V, "Este horno lo encendió por primera vez mi padre, en mil novecientos noventa y uno. Pepe tenía veintitrés años y tenía pelo.", "이 가마에 처음 불을 붙인 건 1991년, 우리 아버지였어. 그때 페페는 스물세 살이었고 머리숱도 있었지."),
(P, "Tenía. En pasado.", "있었죠. 과거형으로."),
(V, "(risas) En dos mil once lo dejamos a medio gas, porque no había trabajo. Durante quince años, la mitad de esta nave ha estado a oscuras. Se notaba al entrar. Se respiraba un aire de fábrica cansada.", "(웃음) 2011년엔 일감이 없어서 반쪽으로만 돌렸어. 15년 동안 이 작업동 절반은 어둠 속에 있었지. 들어오면 느껴졌어. 지친 공장의 공기가 났어."),
(P, "Y frío. En invierno, en la mitad apagada, se veía el aliento.", "그리고 추웠죠. 겨울엔 꺼진 쪽 절반에서 입김이 보였어요."),
(V, "Hoy se respira otra cosa. Y no es por mí. Es por un madrileño que se puso un chaleco amarillo, por mi hija, por Ramón con sus números, por los que hicieron sábados en febrero, y por vosotros, los veintiuno, que empezasteis en enero sin saber si esto acabaría saliendo.", "오늘은 다른 공기가 나. 나 때문이 아니야. 노란 조끼를 입은 마드리드 사람, 내 딸, 숫자를 들고 다니는 라몬, 2월에 토요일 근무를 해 준 사람들, 그리고 이게 잘될지도 모른 채 1월에 들어온 너희 21명 덕분이야."),
(None, "Uno de los nuevos, un chico de veinte años, se pone colorado. Sus compañeros le dan codazos.", "신입 중 스무 살 청년 하나가 얼굴이 빨개진다. 동료들이 팔꿈치로 그를 쿡쿡 찌른다."),
(V, "Y ahora le cedo la palabra a Encarna, que si no, el comité me denuncia.", "그럼 이제 엔카르나에게 말을 넘길게. 안 그러면 노조가 날 고발할 테니까."),
(E, "(sonríe) Un minuto, nada más. En enero, en esta misma nave, discutimos a gritos. Pepe dijo «basta». Y tenía razón.", "(미소 지으며) 1분만요. 1월에 바로 이 작업동에서 우린 고함을 지르며 싸웠어요. 페페가 '그만'이라고 했죠. 그리고 그 말이 옳았어요."),
(V, "Tenía razón, sí. Y a mí me costó reconocerlo.", "그래, 옳았지. 그리고 난 그걸 인정하는 게 힘들었고."),
(E, "Hoy encendemos un horno sin turnos de siete días, con veintiún contratos fijos y con los domingos de las familias. Eso, cuando lo cuento en otras fábricas, no se lo creen. Así que, por favor, que dure.", "오늘 우린 7일 연속 교대 없이, 정규직 21명과 함께, 가족의 일요일을 지키면서 가마에 불을 붙여요. 다른 공장에 이 얘기를 하면 믿질 않아요. 그러니 제발, 오래가게 해요."),
(A, "Que dure. Te lo prometo yo, Encarna. Por escrito, como siempre.", "오래가게요. 내가 약속할게요, 엔카르나. 늘 그렇듯 서면으로."),
(E, "Por escrito y firmado. Que te conozco.", "서면에 서명까지. 내가 당신을 알거든요."),
(V, "Juanjo. Cuando quieras.", "후안호. 준비되면 해."),
(None, "Juanjo se acerca al panel. Pepe le da la llave. Juanjo la gira con la mano izquierda. Se enciende una luz verde. Pepe asiente. Juanjo aprieta el botón rojo del quemador principal. Un silbido largo, después un rugido sordo, y una llama azul aparece detrás del cristal de inspección. Nadie aplaude todavía.", "후안호가 제어판으로 다가간다. 페페가 그에게 열쇠를 건넨다. 후안호가 왼손으로 열쇠를 돌린다. 초록 불이 들어온다. 페페가 고개를 끄덕인다. 후안호가 주 버너의 빨간 버튼을 누른다. 긴 쉬익 소리, 이어서 낮은 굉음, 그리고 점검창 너머로 파란 불꽃이 보인다. 아직 아무도 박수를 치지 않는다."),
(J, "(muy bajo) ¿Ya está?", "(아주 작게) 된 거예요?"),
(P, "Ya está. (mira el termómetro) Ciento veinte grados. Ciento treinta. Va subiendo.", "됐어. (온도계를 보며) 120도. 130도. 올라가고 있어."),
(None, "Entonces sí. Un aplauso que empieza en la puerta y llega hasta el fondo de la nave. Toni silba con dos dedos. Maribel se seca los ojos con la manga y dice que es el polvo.", "그제야 박수가 터진다. 문 쪽에서 시작된 박수가 작업동 끝까지 퍼진다. 토니가 손가락 두 개로 휘파람을 분다. 마리벨은 소매로 눈가를 닦으며 먼지 때문이라고 한다."),
(AD, "(a Paco, en voz baja) Perdone, ¿esto siempre es así? ¿Con aplausos?", "(파코에게 작은 소리로) 저기요, 원래 늘 이래요? 박수 치고?"),
(PA, "No, chaval. Esto pasa una vez cada treinta años. Hazle una foto, que la próxima vez tendrás mi edad.", "아니, 이 친구야. 이건 30년에 한 번 있는 일이야. 사진 찍어 둬. 다음번엔 네가 내 나이일 테니까."),
(AD, "¿Puedo hacerle una foto al quemador?", "버너 사진 찍어도 돼요?"),
(PA, "Al quemador y a Juanjo. Pero a Juanjo pídele permiso, que es tímido.", "버너도 찍고 후안호도 찍어. 근데 후안호한텐 허락받아. 수줍음 많으니까."),
(J, "(a Pepe) Se me ha puesto la piel de gallina. Mira. (le enseña el brazo)", "(페페에게) 소름 돋았어요. 봐요. (팔을 보여 주며)"),
(P, "A mí también. Pero yo llevo manga larga, para que no se me note.", "나도야. 근데 난 긴팔 입었어. 티 안 나게."),
(J, "Pepe… lo del dos mil seis. Tú dijiste una vez que nunca te lo perdonarías.", "페페… 2006년 일이요. 언젠가 절대 자기를 용서 못 할 거라고 했잖아요."),
(P, "Y no me lo perdono. Pero hoy, por lo menos, el horno lo has encendido tú descansado. Eso ya es algo.", "지금도 용서 못 해. 그래도 오늘은 적어도 네가 푹 쉬고 나서 불을 붙였잖아. 그거면 된 거야."),
(J, "Es mucho, Pepe. Es muchísimo.", "많은 거예요, 페페. 엄청 많은 거예요."),
(A, "(a Lucas, en voz baja) Se me ha hecho un nudo en la garganta. No me mires.", "(루카스에게 작은 소리로) 목이 메네요. 쳐다보지 마요."),
(L, "No te miro. Miro el termómetro. Doscientos grados.", "안 봐요. 온도계 보고 있어요. 200도."),
(A, "¿Cuánto tarda en llegar a temperatura?", "온도 다 오르는 데 얼마나 걸려요?"),
(PA, "Tres días, si todo va bien. El jueves, las primeras piezas de sesenta por ciento veinte. Y el viernes, ya en serio.", "다 잘되면 사흘이요. 목요일에 첫 60×120이 나오고, 금요일부터 본격적으로요."),
(L, "Paco, las primeras del jueves, las cincuenta mejores, apártalas. Con cantoneras nuevas y una caja de las de Maribel.", "파코, 목요일 첫 생산분 중에 제일 좋은 50장 따로 빼 줘요. 새 모서리 보호대 대고 마리벨이 만든 상자에 넣어서요."),
(PA, "¿Para Riad?", "리야드용이요?"),
(L, "Para Seúl. Si esta tarde llega lo que espero, claro.", "서울용이요. 오늘 오후에 내가 기다리는 소식이 오면요."),
(P, "Que lleguen o no lleguen, las cincuenta mejores las elijo yo. Lo que haga falta, pero las elijo yo.", "오든 안 오든 제일 좋은 50장은 내가 골라. 뭐가 필요하든 고르는 건 나야."),
(L, "Lo que tú digas, Pepe.", "당신 말대로 해요, 페페."),
(P, "Eso. Vas aprendiendo.", "그렇지. 점점 배우는구나."),

("#", "Escena 3 · 9:15 · Comedor de la fábrica", "장면 3 · 오전 9시 15분 · 공장 식당"),
(None, "En el comedor, cafés y una bandeja de coca de llanda que ha traído la mujer de Paco. Los nuevos se sientan juntos, todavía sin atreverse a mezclarse con los veteranos. Encarna se acerca a la mesa de Lucas y Amparo con su taza.", "식당에는 커피와 파코의 아내가 가져온 코카 데 야냐 한 쟁반. 신입들은 아직 고참들 사이에 섞일 엄두를 못 내고 자기들끼리 모여 앉는다. 엔카르나가 컵을 들고 루카스와 암파로의 테이블로 온다."),
(E, "Lucas, en el comedor se dice que lo de Corea ya está hecho. ¿Es verdad o es cosa de Toni?", "루카스, 식당에선 한국 건이 이미 됐다고들 하던데요. 사실이에요, 아니면 토니 얘기예요?"),
(L, "Es medio verdad. Estamos dentro, pero falta el papel. Si llega, serán noventa mil metros en dos años.", "반만 사실이에요. 들어가긴 했는데 서류가 아직이에요. 오면 2년간 9만 제곱미터예요."),
(E, "Noventa mil. ¿Y eso a qué horno va?", "9만이라. 그건 어느 가마로 가요?"),
(L, "Al uno, sobre todo. Por eso necesitábamos que se encendiera bien.", "주로 1호기요. 그래서 제대로 불이 붙어야 했던 거고요."),
(E, "Entonces te pido lo mismo que en enero: que nadie se entere de un turno nuevo por un papel en el tablón.", "그럼 1월에 했던 부탁 그대로 할게요. 새 교대 근무를 게시판 종이로 알게 되는 사람이 없게 해 줘요."),
(A, "Nadie. Si Corea entra, primero se lo contamos al comité y después lo ponemos en el tablón. En ese orden.", "아무도요. 한국 건이 확정되면 먼저 노조에 알리고 그다음에 게시판에 붙일게요. 그 순서로."),
(E, "En ese orden. Me lo apunto, Amparo.", "그 순서로. 적어 둘게요, 암파로."),
(V, "(llega con un café) ¿Ya me la estáis liando, Encarna?", "(커피를 들고 오며) 벌써 나한테 일 꾸미는 거야, 엔카르나?"),
(E, "No, don Vicente. Hoy solo vengo a dar las gracias. Mañana vuelvo a ser la del comité.", "아니에요, 사장님. 오늘은 고맙다는 말만 하러 왔어요. 내일 다시 노조 대표로 돌아갈게요."),
(V, "Me alegro. Porque hoy no quiero discutir. Hoy quiero mirar el horno.", "다행이야. 오늘은 다투고 싶지 않거든. 오늘은 가마만 보고 싶어."),
(P, "(desde la mesa de al lado) El horno no se mira, Vicente, se escucha. Y ahora mismo dice que va bien.", "(옆 테이블에서) 가마는 보는 게 아니라 듣는 거예요, 비센테. 그리고 지금은 잘 가고 있다고 하네요."),
(V, "¿A cuánto está?", "몇 도야?"),
(P, "Trescientos diez. Va subiendo. A este paso, el jueves tenemos piezas.", "310도. 올라가고 있어요. 이대로면 목요일에 타일이 나와요."),
(V, "(pensativo) El jueves… Pepe, ¿te acuerdas de lo que dijo mi padre cuando lo encendimos en el noventa y uno?", "(생각에 잠겨) 목요일이라… 페페, 91년에 불 붙였을 때 우리 아버지가 뭐라고 했는지 기억나?"),
(P, "«Este horno lo apagará otro». Me acuerdo.", "'이 가마는 다른 사람이 끌 거다.' 기억나요."),
(V, "Pues acertó a medias. Lo ha encendido otro también.", "반은 맞았네. 켠 것도 다른 사람이었으니까."),
(A, "Papá, ¿qué quieres decir con eso?", "아빠, 그게 무슨 뜻이에요?"),
(V, "Nada, hija. Cosas de viejo. Cómete la coca, que se enfría.", "아무것도 아니야, 얘야. 늙은이 얘기지. 코카 먹어, 식기 전에."),
(P, "La coca no se enfría, Vicente. Ya viene fría.", "코카는 안 식어요, 비센테. 원래 차갑게 먹는 거예요."),

("#", "Escena 4 · 11:20 · Despacho de exportación", "장면 4 · 오전 11시 20분 · 수출팀 사무실"),
(None, "Lucas y Amparo revisan el calendario de embarques de mayo. En la pared, el mapa: rojo en Monterrey, amarillo en Miami y Texas, azul en Bogotá, verde en Riad. Debajo, el trozo de baldosa de 1958. Suena el aviso de un correo nuevo.", "루카스와 암파로가 5월 선적 일정을 점검한다. 벽에는 지도. 몬테레이에 빨강, 마이애미와 텍사스에 노랑, 보고타에 파랑, 리야드에 초록. 그 아래 1958년 타일 조각. 새 메일 알림이 울린다."),
(L, "(lee la pantalla) Hanul Construcción. Asunto: «Notificación de decisión — Proveedor de pavimentos, Hanul Lumière».", "(화면을 읽으며) 한울건설. 제목: '결정 통보 — 바닥재 공급업체, 한울 뤼미에르.'"),
(A, "Léelo. Despacio.", "읽어 봐요. 천천히."),
(L, "«Nos complace comunicarles que el comité de compras de Hanul Construcción ha seleccionado a Cerámicas Albalat como proveedor de pavimento cerámico para los tres complejos de la marca Hanul Lumière, a través de su distribuidor exclusivo Seorin Interiores…»", "'한울건설 구매위원회가 서린 인테리어를 독점 유통사로 하여, 세라미카스 알발라트를 한울 뤼미에르 브랜드 3개 단지의 세라믹 바닥재 공급업체로 선정했음을 알려 드리게 되어 기쁩니다…'"),
(A, "Sigue.", "계속해요."),
(L, "«…una vez superado el control de calidad de las muestras recibidas el 16 de abril, con las condiciones acordadas el 4 de abril, incluida la cláusula de volumen mínimo. La firma del contrato tendrá lugar en mayo, y las primeras muestras de producción deberán llevar ya el código QR definitivo»." , "'…4월 16일 접수한 샘플의 품질 검사를 통과하였으므로, 4월 4일 합의한 조건(최소 물량 조항 포함)으로 진행합니다. 계약 서명은 5월에 하며, 첫 양산 샘플에는 최종 QR 코드가 부착되어야 합니다.'"),
(A, "¿Han pasado los cuarenta y dos puntos?", "42개 항목을 다 통과했다고요?"),
(L, "Los cuarenta y dos. Y con la cláusula de los treinta mil metros. Marta va a decir que ya lo sabía.", "42개 전부요. 3만 제곱미터 조항까지 그대로고요. 마르타는 그럴 줄 알았다고 하겠죠."),
(A, "Marta siempre lo sabe todo antes. (lo mira) Lucas. Noventa mil metros. Y el horno uno encendido el mismo día.", "마르타는 늘 다 먼저 알죠. (그를 보며) 루카스. 9만 제곱미터예요. 그리고 1호기에 불 붙인 바로 그날에."),
(L, "Hay días que parecen escritos por un guionista malo. Demasiadas cosas buenas juntas.", "가끔은 서툰 작가가 쓴 것 같은 날이 있어요. 좋은 일이 너무 한꺼번에 오는 날."),
(A, "Pues disfrútalo. Que luego vienen los días escritos por un guionista peor.", "그럼 즐겨요. 그다음엔 더 서툰 작가가 쓴 날들이 오니까."),
(None, "Suena el teléfono fijo. En la pantalla: +82.", "유선 전화가 울린다. 화면에 +82."),
(K, "Señor Ferrer, buenas tardes desde Seúl. Bueno, para ustedes, buenos días. ¿Ha leído el correo?", "페레르 씨, 서울에서 인사드립니다. 아, 거긴 아침이겠네요. 메일 읽으셨나요?"),
(L, "Lo acabamos de leer, señora Kim. La señora Albalat está aquí conmigo. Le pongo el altavoz.", "방금 읽었습니다, 김 대표님. 알발라트 씨도 같이 있어요. 스피커로 돌릴게요."),
(K, "Mis felicitaciones a los dos. El director Park me ha pedido que les diga una cosa personalmente: que la noche del karaoke fue decisiva. Que no se lo tomen a mal.", "두 분 모두 축하드려요. 박 상무님이 직접 전해 달라는 말이 있어요. 노래방 밤이 결정적이었다고요. 언짢게 듣지 마시래요."),
(A, "(mira a Lucas) ¿El karaoke? ¿No fueron las cantoneras?", "(루카스를 보며) 노래방이요? 모서리 보호대가 아니고요?"),
(K, "Las cantoneras les dieron la nota técnica. El karaoke les dio la confianza. En Corea hacen falta las dos cosas.", "모서리 보호대로 기술 점수를 받았고, 노래방으로 신뢰를 얻은 거예요. 한국에선 둘 다 필요해요."),
(L, "Entonces dígale al director Park que la próxima vez canto yo dos canciones.", "그럼 박 상무님께 다음엔 제가 두 곡 부르겠다고 전해 주세요."),
(K, "Se lo diré. Él dice que la próxima vez canta en Onda. Ahora, lo importante: las muestras de producción. ¿Cuándo podrían enviarlas?", "전할게요. 상무님은 다음엔 온다에서 부르겠다고 하세요. 자, 중요한 얘기요. 양산 샘플은 언제 보내실 수 있나요?"),
(L, "Hoy hemos encendido el horno nuevo. Las primeras piezas salen el jueves. Las cincuenta mejores irán a Seúl por avión la semana que viene.", "오늘 새 가마에 불을 붙였어요. 첫 타일은 목요일에 나와요. 그중 제일 좋은 50장을 다음 주에 항공편으로 서울에 보낼게요."),
(K, "¿Del horno nuevo? ¿Las primeras piezas de un horno nuevo?", "새 가마에서요? 새 가마의 첫 타일을요?"),
(A, "Las primeras. Elegidas una a una por nuestro jefe de planta, que lleva cuarenta años en la fábrica.", "첫 타일이요. 이 공장에서 40년 일한 공장장이 한 장씩 고를 거예요."),
(K, "Eso… eso en Corea tiene un significado muy bonito. Lo primero de algo nuevo se ofrece a quien más se respeta. Se lo contaré al director Park tal cual.", "그건… 한국에선 아주 아름다운 의미가 있어요. 새로운 것의 첫 번째는 가장 존중하는 사람에게 드리거든요. 박 상무님께 그대로 전할게요."),
(L, "Y irán con el código QR por pieza que pidió su equipo de calidad. Maribel ha terminado el diseño este fin de semana.", "그리고 품질팀이 요청한 낱장별 QR 코드도 붙여서 보낼게요. 마리벨이 이번 주말에 디자인을 끝냈어요."),
(K, "Perfecto. El director Park preguntará también por el olor del cartón. No se ría: el año pasado rechazaron a un proveedor porque las cajas olían a humedad.", "완벽해요. 박 상무님은 상자 냄새도 물어볼 거예요. 웃지 마세요. 작년에 상자에서 습한 냄새가 난다고 공급업체 하나를 떨어뜨렸거든요."),
(A, "Cartón nuevo, secado en nave cerrada. Y si quiere, le mandamos también el informe de humedad.", "새 상자고, 밀폐된 창고에서 건조해요. 원하시면 습도 보고서도 같이 보내 드릴게요."),
(K, "Eso sí que no me lo había ofrecido nadie. Lo voy a poner en mi presentación.", "그건 아무도 제안한 적 없는 거예요. 제 발표 자료에 넣을게요."),
(L, "Y lo de las primeras piezas, cuénteselo al director Park tal cual. Otra cosa, señora Kim: ¿sigue en pie lo de Yu-na?", "그리고 첫 타일 얘기는 박 상무님께 그대로 전해 주세요. 하나 더요, 김 대표님. 유나 씨 건은 아직 유효한가요?"),
(K, "¿Lo de que venga a Onda en verano a aprender? Sigue en pie. Está tan ilusionada que ya se ha comprado una guía de Castellón.", "여름에 온다에 와서 배우는 거요? 유효해요. 너무 들떠서 벌써 카스테욘 여행 책까지 샀어요."),
(A, "Dígale que la guía no sirve. Aquí lo importante no viene en las guías: viene en las sobremesas.", "그 책은 소용없다고 전해 주세요. 여기서 중요한 건 책에 안 나와요. 식후 담소에서 나와요."),
(K, "(ríe) Se lo diré. Hasta pronto. Y felicidades otra vez: por el horno y por Hanul. Hoy es un buen día en dos países.", "(웃으며) 전할게요. 또 연락드려요. 다시 한번 축하드려요. 가마도, 한울도요. 오늘은 두 나라에서 좋은 날이네요."),
(None, "Lucas cuelga. Amparo abre el cajón y saca la chincheta que guardó en marzo: morada.", "루카스가 전화를 끊는다. 암파로가 서랍을 열어 3월에 넣어 둔 압정을 꺼낸다. 보라색이다."),
(A, "La de Seúl. ¿La pones tú o la pongo yo?", "서울 거예요. 당신이 꽂을래요, 내가 꽂을래요?"),
(L, "Esta, juntos. Que la próxima ya no sé dónde va.", "이건 같이요. 다음 건 어디 꽂힐지 모르니까."),
(None, "Clavan la chincheta morada en Seúl, los dos con un dedo, como quien aprieta un botón. En ese momento se abre la puerta. Es Vicente, todavía con el chaleco del horno.", "둘이 손가락 하나씩 얹어 버튼을 누르듯 서울에 보라색 압정을 꽂는다. 그 순간 문이 열린다. 아직 가마 작업동 조끼를 입은 비센테다."),
(V, "¿Morada? ¿Eso es Seúl?", "보라색? 그게 서울이야?"),
(L, "Seúl. Ha llegado esta mañana. Noventa mil metros y la exclusividad con Seorin.", "서울이요. 오늘 아침에 왔어요. 9만 제곱미터에, 서린과 독점이요."),
(V, "(se queda mirando el mapa un rato largo) Mi abuelo empezó con un horno de leña y un burro. Y mirad esto.", "(한참 지도를 바라보며) 우리 할아버지는 장작 가마 하나랑 당나귀 한 마리로 시작했어. 그런데 이걸 봐."),
(A, "Papá, ¿estás bien?", "아빠, 괜찮아요?"),
(V, "Estoy muy bien. Precisamente por eso. (se vuelve hacia los dos) El lunes que viene, a las nueve, reunión de toda la plantilla en el comedor. Toda. Los del turno de noche también.", "아주 괜찮아. 바로 그래서야. (두 사람 쪽으로 돌아서며) 다음 주 월요일 9시, 식당에서 전 직원 회의. 전부 다. 야간조도."),
(L, "¿De qué se trata?", "무슨 일인데요?"),
(V, "De lo que hablamos en el coche, en Riad. Ya va siendo hora. Y hoy, que se ha encendido el uno, me he dado cuenta de que ya no tengo excusas.", "리야드에서 차 안에서 얘기했던 거. 때가 됐어. 오늘 1호기에 불이 들어오는 걸 보고, 이제 더는 핑계가 없다는 걸 깨달았어."),
(None, "Vicente sale. Amparo se queda mirando la puerta. Lucas mira la chincheta morada. Desde la nave del horno uno llega, muy lejano, el rugido constante del quemador.", "비센테가 나간다. 암파로는 문을 바라보고 서 있다. 루카스는 보라색 압정을 본다. 1호기 작업동 쪽에서 아주 멀리, 버너의 한결같은 굉음이 들려온다."),
]

PRE = [
("text", "장면 미리보기", "대화문을 읽기 전에 줄거리를 확인하고, 아래 질문의 답을 찾으며 읽어 보세요.", [
 "5월 4일 월요일 새벽. 6주의 '수술'을 마친 1호기 앞에서 페페는 5시부터 네 번째 점검을 하고 있다. 8시, 공장 사람들이 모두 모인 가운데 비센테와 노조 대표 엔카르나가 짧게 말하고, 2006년 사고로 왼손 손가락 둘을 잃은 후안호가 열쇠를 돌려 버너에 불을 붙인다. 온도가 오르는 동안 루카스는 목요일 첫 생산분에서 가장 좋은 50장을 따로 빼 달라고 부탁한다. 오전 11시 20분, 서울의 한울건설에서 정식 선정 통보가 오고 김민서가 전화한다. 두 사람은 지도의 서울에 보라색 압정을 꽂는다. 그리고 비센테가 다음 주 월요일 전 직원 회의를 소집한다.",
 "듣기 질문 ① 페페는 왜 직접 불을 붙이지 않고 후안호에게 맡기는가? 엔카르나가 '오래가게 해 달라'고 한 것은 무엇인가?",
 "듣기 질문 ② 한울의 결정 통보에는 어떤 조건이 붙어 있는가? 김민서는 결정의 두 가지 이유를 무엇이라고 하는가?",
 "듣기 질문 ③ 새 가마의 '첫 타일'을 서울로 보내는 것이 한국에서 왜 특별한 의미가 있는가? 비센테가 '더는 핑계가 없다'고 한 것은 무슨 뜻일까?",
]),
]

